using System;using System.IO;using System.Linq;using System.Text;using System.Security.Cryptography;using System.Collections.Generic;using System.ComponentModel;using System.Windows.Media.Media3D;using System.Drawing;

namespace GearLab {

 public sealed class RobotStyleParameters {

  public double Slimness{get;set;}public double JointCompactness{get;set;}public double Smoothness{get;set;}public double Roundness{get;set;}public double Taper{get;set;}public double Symmetry{get;set;}public double PanelCoverage{get;set;}public bool HiddenFasteners{get;set;}public double MechanicalExposure{get;set;}public double AccentColorCoverage{get;set;}public string Profile{get;set;}public double Strength{get;set;}

  public RobotStyleParameters(){Slimness=.78;JointCompactness=.85;Smoothness=.7;Roundness=.85;Taper=.72;Symmetry=1;PanelCoverage=.72;HiddenFasteners=true;MechanicalExposure=0;AccentColorCoverage=.32;Profile="oval";Strength=1;}

  public static RobotStyleParameters Preset(string name){var s=new RobotStyleParameters();if(name=="Ultra Slim"){s.Slimness=1;s.JointCompactness=1;s.Taper=1;s.PanelCoverage=.5;s.AccentColorCoverage=.18;}if(name=="Lightweight"){s.Slimness=.95;s.Taper=.9;s.PanelCoverage=.4;s.HiddenFasteners=false;s.MechanicalExposure=.2;s.AccentColorCoverage=.2;}if(name=="High Strength"){s.Slimness=.4;s.JointCompactness=.5;s.Taper=.35;s.Strength=1.4;s.HiddenFasteners=false;s.Profile="rounded_rectangle";}if(name=="Easy Print"){s.Slimness=.65;s.Smoothness=.3;s.Roundness=.5;s.Taper=.5;s.HiddenFasteners=false;s.Profile="rounded_rectangle";}return s;}

 }

 public sealed class BodyPhysicalComponent {public string Preview{get;set;}public override string ToString(){return Label;}public string Id{get;set;}public string Label{get;set;}public string Step{get;set;}public string Fidelity{get;set;}}

 public sealed class ProceduralBodySettings {

  [DisplayName("Стыковочные фланцы и замкнутые переходы")]public bool Connected{get;set;}

  [DisplayName("Корпус по референсу · монокок")]public bool ReferenceDesign{get;set;}

  [DisplayName("Г-образные звенья · РОБОТ1.blend")]public bool BlenderDesign{get;set;}

  [Browsable(false)]public List<BodyPhysicalComponent> Components{get;set;}

  [Browsable(false),DisplayName("Включить процедурный корпус")]public bool Enabled{get;set;}[DisplayName("Автоматическое перестроение")]public bool AutoRegenerate{get;set;}[DisplayName("Вариант")]public string Variant{get;set;}[DisplayName("Параметры стиля")]public RobotStyleParameters Style{get;set;}[DisplayName("Минимальная стенка, мм")]public double MinWall{get;set;}[DisplayName("Стенка каркаса, мм")]public double FrameWall{get;set;}[DisplayName("Стенка оболочки, мм")]public double SkinWall{get;set;}[DisplayName("Монтажный зазор, мм")]public double Clearance{get;set;}[DisplayName("Допускаемое напряжение материала, МПа")]public double AllowableStressMPa{get;set;}[DisplayName("Плотность материала, кг/м³")]public double Density{get;set;}[DisplayName("Радиус изгиба проводки, мм")]public double CableBendRadius{get;set;}[DisplayName("Посадочный диаметр вставки, мм")]public double InsertDiameter{get;set;}[DisplayName("Длина вставки, мм")]public double InsertLength{get;set;}[DisplayName("Радиальный зазор вала, мм")]public double ShaftFit{get;set;}[DisplayName("Поле от края стола, мм")]public double PrintMargin{get;set;}

  public ProceduralBodySettings(){Connected=true;Components=new List<BodyPhysicalComponent>();Enabled=true;AutoRegenerate=true;Variant="Reference";Style=new RobotStyleParameters();MinWall=2.4;FrameWall=3.2;SkinWall=2;Clearance=.35;AllowableStressMPa=12;Density=1270;CableBendRadius=16;InsertDiameter=4.6;InsertLength=5.2;ShaftFit=.1;PrintMargin=6;}

  public void Validate(){if(BlenderDesign&&!ReferenceDesign)throw new Exception("Г-образный корпус требует режима корпуса по референсу.");if(ReferenceDesign&&!Connected)throw new Exception("Корпус по референсу требует включённых стыковочных фланцев.");foreach(var property in typeof(ProceduralBodySettings).GetProperties().Where(p=>p.PropertyType==typeof(double)))if(!MechanismCad.Finite((double)property.GetValue(this,null)))throw new Exception("Некорректное число: "+property.Name);if(Style==null||!new[]{"Reference","Ultra Slim","Lightweight","High Strength","Easy Print"}.Contains(Variant))throw new Exception("Неизвестный процедурный стиль.");foreach(var p in typeof(RobotStyleParameters).GetProperties().Where(p=>p.PropertyType==typeof(double)&&p.Name!="Strength")){double value=(double)p.GetValue(Style,null);if(!MechanismCad.Finite(value)||value<0||value>1)throw new Exception(p.Name+": значение 0–1.");}if(!MechanismCad.Finite(Style.Strength)||Style.Strength<.5||Style.Strength>3||!(Style.Profile=="oval"||Style.Profile=="rounded_rectangle"))throw new Exception("Некорректный профиль или коэффициент усиления.");if(MinWall<1.2||MinWall>20||FrameWall<MinWall||FrameWall>30||SkinWall<1||SkinWall>8||Clearance<.05||Clearance>2||AllowableStressMPa<.1||AllowableStressMPa>250||Density<100||Density>20000||CableBendRadius<3||CableBendRadius>100||InsertDiameter<3||InsertDiameter>15||InsertLength<3||InsertLength>20||ShaftFit<.02||ShaftFit>1||PrintMargin<0||PrintMargin>25)throw new Exception("Проверьте стенки, допускаемое напряжение, зазоры, вставки и параметры печати.");}

 }

