 public sealed class ProceduralBodyResult {public List<BodyMate> Mates{get;set;}public List<BodyGeneratedPart> Parts{get;set;}public List<BodyGenerationIssue> Issues{get;set;}public Dictionary<string,string> Modules{get;set;}public List<string> ChangedModules{get;set;}public List<string> RepairedParts{get;set;}public List<BodyProtectionVolume> ProtectedVolumes{get;set;}public double MassKg{get;set;}public double MinFrameRadius{get;set;}public double NominalStress{get;set;}public int Segments{get;set;}public bool GeometryValid{get;set;}public bool ReadyForManufacture{get;set;}public double Seconds{get;set;}}

 public sealed class RobotGeneratedBody {public string Fingerprint{get;set;}public string SpecJson{get;set;}public ProceduralBodyResult Result{get;set;}public DateTime GeneratedUtc{get;set;}}

 public static class ProceduralBodySpec {

  public const string EngineVersion="gearlab-blender-elbow-2";

  public static string Fingerprint(RobotDocument doc,RobotJoint j,ProceduralBodySettings settings){var omitted=new HashSet<string>(new[]{"GeneratedBody","BodyGenerator","Position","Name","Appearance","ForceX","ForceY","ForceZ"});var fields=typeof(RobotJoint).GetProperties().Where(p=>p.CanRead&&p.GetIndexParameters().Length==0&&!omitted.Contains(p.Name)&&!Attribute.IsDefined(p,typeof(System.Web.Script.Serialization.ScriptIgnoreAttribute))).ToDictionary(p=>p.Name,p=>p.GetValue(j,null));var copy=CADDocument.Serializer().DeserializeObject(CADDocument.Serializer().Serialize(fields)) as Dictionary<string,object>;if(j.CustomAxis==null)copy.Remove("CustomAxis");var axisChildren=doc.Joints.Where(x=>x.ParentId==j.Id&&x.CustomAxis!=null).Select(x=>new{x.Id,x.CustomAxis}).ToArray();if(axisChildren.Length>0)copy["ChildCustomAxes"]=axisChildren;if(j.TrainSettings==null){copy.Remove("TrainSettings");copy.Remove("TrainOutput");}copy.Remove("GeneratedBody");copy.Remove("BodyGenerator");foreach(string key in new[]{"Position","Name","Appearance","ForceX","ForceY","ForceZ"})copy.Remove(key);var value=new{Engine=EngineVersion,ReferenceGripper=doc.ReferenceGripper,Joint=copy,Settings=settings,Children=doc.Joints.Where(x=>x.ParentId==j.Id).Select(x=>new{x.Id,x.AxisReversed,x.OffsetX,x.OffsetY,x.OffsetZ,x.MotorFrame,x.MotorLength,x.MotorOffsetX,x.MotorOffsetY,x.Wall,x.GearboxDiameter,x.GearboxLength,x.Mode,Settings=x.BodyGenerator}),Load=doc.Joints.Where(x=>doc.Descendant(x.Id,j.Id)).Select(x=>new{x.Id,x.Payload,x.MotorMass,x.EndX,x.EndY,x.EndZ,x.ForceX,x.ForceY,x.ForceZ,BodyMass=x.Id!=j.Id&&x.GeneratedBody!=null?x.GeneratedBody.Result.MassKg:0}),ParentMount=j.ParentId==null?0:ParentMount(doc,j),Safety=doc.SafetyFactor,Gravity=doc.Gravity,Edits=doc.BodyEdits.Where(e=>e.PartId.StartsWith(j.Id+"_proc_",StringComparison.Ordinal))};using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(CADDocument.Serializer().Serialize(value)))).Replace("-","");}

  public static Dictionary<string,object> Build(RobotDocument doc,RobotJoint j,ProceduralBodySettings settings,RobotBuild mechanical=null,string physicalStep=null){settings.Validate();if(j.Linear)throw new Exception("Для линейного привода пока нет процедурного монтажного шаблона. Используйте CAD-редактор.");var axis=RobotMath.Frame(j.Axis);axis.Invert();var end=axis.Transform(new Vector3D(j.EndX,j.EndY,j.EndZ));var bounds=BodyLoadEnvelope.Calculate(doc,j,mechanical);double current=0;if(mechanical!=null){var load=RobotSolver.Solve(mechanical).Joints.FirstOrDefault(x=>x.Id==j.Id);if(load!=null){if(load.Unit!="Н·м")throw new Exception("Для процедурного корпуса нужен вращательный шарнир, а не усилие в Н.");current=load.Required*1000;}}double conservativeMoment=bounds.MomentNmm;double outputTop=Math.Max(15,j.Wall+10+(j.BodyStyle==RobotBodyStyle.Закрытый_трубчатый?3*j.Wall:0));var components=new List<object>();if(settings.Components!=null)components.AddRange(settings.Components.Select(c=>(object)c));if(physicalStep!=null)components.Add(new{Id="selected_components",Label="Параметрическая механика GearLab",Step=physicalStep,Fidelity="parametric"});return new Dictionary<string,object>{{"Version",1},{"Connected",settings.Connected},{"ReferenceDesign",settings.ReferenceDesign},{"BlenderDesign",settings.BlenderDesign},{"Children",doc.Joints.Where(c=>c.ParentId==j.Id).Select(c=>Child(doc,j,c,settings)).ToArray()},{"Root",j.ParentId==null},{"ParentMountThickness",j.ParentId==null?Math.Max(10,settings.MinWall*2+settings.InsertDiameter):ParentMount(doc,j)},{"GroundDepth",j.ParentId==null&&j.Mode==RobotJointMode.Вращение_Z&&!j.AxisReversed?Math.Max(0,j.OffsetZ):0},{"Engine",EngineVersion},{"JointId",j.Id},{"Name",j.Name},{"End",new[]{end.X,end.Y,end.Z}},{"Variant",settings.Variant},{"Style",settings.Style},{"Motor",new{Frame=j.MotorFrame,Length=j.MotorLength,Pitch=j.MotorBoltPitch,Pilot=j.MotorPilot,Shaft=j.MotorShaft,ShaftLength=j.MotorShaftLength,Bolt=j.MotorBolt,X=j.MotorOffsetX,Y=j.MotorOffsetY}},{"Reducer",new{Diameter=j.GearboxDiameter,Length=j.GearboxLength}},{"Bearing",new{Outer=j.BearingOuter,Inner=j.BearingInner,Width=j.BearingWidth}},{"Mechanical",new{Plate=Math.Max(settings.MinWall,j.Wall),Wall=settings.MinWall,MinWall=settings.MinWall,FrameWall=settings.FrameWall,SkinWall=settings.SkinWall,Clearance=settings.Clearance,AllowableStressMPa=settings.AllowableStressMPa,Density=settings.Density,CableDiameter=j.CableDiameter,CableBendRadius=settings.CableBendRadius,InsertDiameter=settings.InsertDiameter,InsertLength=settings.InsertLength,Bolt=j.BoltDiameter,ShaftFit=settings.ShaftFit,PrintMargin=settings.PrintMargin,Printer=new[]{256,256,256},DesignMomentNmm=Math.Max(current,conservativeMoment),DesignTorqueNmm=Math.Max(conservativeMoment,Math.Max(current,j.MotorTorque*j.Reduction*j.Efficiency*1000)),AxialForceN=bounds.ForceN,LoadEnvelope=bounds,ReferenceDiameter=j.SkinDiameter,OutputTop=outputTop}},{"Components",components},{"PreviousModules",j.GeneratedBody==null?null:j.GeneratedBody.Result.Modules}};}

  static double ParentMount(RobotDocument doc,RobotJoint j){var parent=doc.Find(j.ParentId);var settings=parent==null||parent.BodyGenerator==null?new ProceduralBodySettings():parent.BodyGenerator;return Math.Max(10,settings.MinWall*2+settings.InsertDiameter);}

  static object Child(RobotDocument doc,RobotJoint parent,RobotJoint child,ProceduralBodySettings settings){var local=RobotMath.Frame(parent.Axis);local.Invert();var pose=RobotMath.Frame(child.Axis)*RobotMath.Translation(parent.EndX+child.OffsetX,parent.EndY+child.OffsetY,parent.EndZ+child.OffsetZ)*local;var own=child.BodyGenerator??settings;return new{Id=child.Id,Transform=CADNativeBridge.Transform(pose),Motor=new{Frame=child.MotorFrame,Length=child.MotorLength,Pitch=child.MotorBoltPitch,Pilot=child.MotorPilot,Shaft=child.MotorShaft,ShaftLength=child.MotorShaftLength,Bolt=child.MotorBolt,X=child.MotorOffsetX,Y=child.MotorOffsetY},Reducer=new{Diameter=child.GearboxDiameter,Length=child.GearboxLength},Bearing=new{Outer=child.BearingOuter,Inner=child.BearingInner,Width=child.BearingWidth},Mechanical=new{Plate=child.Wall,MinWall=own.MinWall,Clearance=own.Clearance,InsertDiameter=own.InsertDiameter}};}

  public static RobotGeneratedBody Generate(CADKernel kernel,RobotDocument doc,RobotJoint joint,ProceduralBodySettings settings,string physicalStep=null){var spec=Build(doc,joint,settings,null,physicalStep);var edits=doc.BodyEdits.Where(e=>e.PartId.StartsWith(joint.Id+"_proc_",StringComparison.Ordinal)&&e.NativeStep!=null).ToDictionary(e=>e.PartId.Substring((joint.Id+"_proc_").Length),e=>(object)new{Step=e.NativeStep,Shift=e.NativeShift});if(edits.Count>0)spec["Overrides"]=edits;var result=kernel.Run(new CADDocument(),"body_generate",null,null,null,new Dictionary<string,object>{{"Spec",spec}});if(result.Procedural==null)throw new Exception("Ядро не вернуло процедурный корпус.");foreach(var part in result.Procedural.Parts){var body=result.Bodies.Single(x=>x.Id==part.Id);body.ReadMesh();part.Step=Convert.ToBase64String(File.ReadAllBytes(part.StepPath));part.Preview=CADMeshCodec.Encode(body.Display);part.Volume=body.Volume;part.Center=body.Center;part.Bounds=body.Bounds;part.StepPath=null;}return new RobotGeneratedBody{Fingerprint=Fingerprint(doc,joint,settings),SpecJson=CADDocument.Serializer().Serialize(spec),Result=result.Procedural,GeneratedUtc=DateTime.UtcNow};}

  public static CadPart Part(string id,BodyGeneratedPart data){var mesh=CADMeshCodec.Decode(data.Preview);var p=new CadPart(id,data.Label,"housing",ColorTranslator.FromHtml(data.Color)){NativeStep=data.Step,NativeVolume=data.Volume,NativeCentre=new Point3D(data.Center[0],data.Center[1],data.Center[2]),MeshOverride=mesh,PrintAngles=data.PrintAngles};var b=data.Bounds;p.Sections.Add(new CadSection(b[2],b[5],CadLoop.Polygon(new[]{new PointF((float)b[0],(float)b[1]),new PointF((float)b[3],(float)b[1]),new PointF((float)b[3],(float)b[4]),new PointF((float)b[0],(float)b[4])}),null));return p;}

 }

